mapper.update:
merge into t_tq_schedule_result a USING (
select #{schedule.scheduleDate} schedule_date, #{schedule.cxBatchNo,jdbcType=VARCHAR} cx_batch_no, #{schedule.batchNo,jdbcType=VARCHAR} batch_no, #{schedule.orderNo,jdbcType=VARCHAR} order_no, #{schedule.beadCode,jdbcType=VARCHAR} bead_code, #{schedule.steelRingCode,jdbcType=VARCHAR} steel_ring_code, #{schedule.triangleGlueCode,jdbcType=VARCHAR} triangle_glue_code, #{schedule.glueCode,jdbcType=VARCHAR} glue_code, #{schedule.mouthPlateCode,jdbcType=VARCHAR} mouth_plate_code, #{schedule.specSize,jdbcType=VARCHAR} spec_size, #{schedule.machineId,jdbcType=VARCHAR} machine_id, #{schedule.unitConsume,jdbcType=DOUBLE} unit_consume, #{schedule.stockQty,jdbcType=DOUBLE} stock_qty, #{schedule.supplyTime,jdbcType=DOUBLE} supply_time, #{schedule.midPlanQty,jdbcType=DOUBLE} mid_plan_qty, #{schedule.midProduceOrder,jdbcType=DOUBLE} mid_produce_order, #{schedule.midSysAnalysis,jdbcType=VARCHAR} mid_sys_analysis, #{schedule.midHandAnalysis,jdbcType=VARCHAR} mid_hand_analysis, #{schedule.nightPlanQty,jdbcType=DOUBLE} night_plan_qty, #{schedule.nightProduceOrder,jdbcType=DOUBLE} night_produce_order, #{schedule.nightSysAnalysis,jdbcType=VARCHAR} night_sys_analysis, #{schedule.nightHandAnalysis,jdbcType=VARCHAR} night_hand_analysis, #{schedule.dayPlanQty,jdbcType=DOUBLE} day_plan_qty, #{schedule.dayProduceOrder,jdbcType=DOUBLE} day_produce_order, #{schedule.daySysAnalysis,jdbcType=VARCHAR} day_sys_analysis, #{schedule.dayHandAnalysis,jdbcType=VARCHAR} day_hand_analysis, #{schedule.nextMidPlanQty,jdbcType=DOUBLE} next_mid_plan_qty, #{schedule.nextMidProduceOrder,jdbcType=DOUBLE} next_mid_produce_order, #{schedule.nextMidSysAnalysis,jdbcType=VARCHAR} next_mid_sys_analysis, #{schedule.nextMidHandAnalysis,jdbcType=VARCHAR} next_mid_hand_analysis, #{schedule.cxClass1Plan,jdbcType=DOUBLE} cx_class1_plan, #{schedule.cxClass2Plan,jdbcType=DOUBLE} cx_class2_plan, #{schedule.cxClass3Plan,jdbcType=DOUBLE} cx_class3_plan, #{schedule.cxClass4Plan,jdbcType=DOUBLE} cx_class4_plan, #{schedule.cxClass5Plan,jdbcType=DOUBLE} cx_class5_plan, #{schedule.isRelease,jdbcType=VARCHAR} is_release, #{schedule.markCloseOutTip,jdbcType=VARCHAR} mark_close_out_tip, #{schedule.productionStatus,jdbcType=VARCHAR} production_status, #{schedule.delFlag,jdbcType=VARCHAR} del_flag, #{schedule.createBy,jdbcType=VARCHAR} create_by, #{schedule.createTime} create_time, #{schedule.remark,jdbcType=VARCHAR} remark, #{schedule.dataSource,jdbcType=VARCHAR} data_Source from dual
) b ON (a.schedule_date = b.schedule_date AND a.bead_code = b.bead_code AND a.machine_id = b.machine_id AND a.del_flag = '0' ) WHEN MATCHED THEN UPDATE SET a.mid_plan_qty = b.mid_plan_qty, a.mid_hand_analysis = b.mid_hand_analysis, a.night_plan_qty = b.night_plan_qty, a.night_hand_analysis = b.night_hand_analysis, a.day_plan_qty = b.day_plan_qty, a.day_hand_analysis = b.day_hand_analysis, a.next_mid_plan_qty = b.next_mid_plan_qty, a.next_mid_hand_analysis = b.next_mid_hand_analysis, a.update_by = b.create_by, a.update_time = sysdate, a.remark = b.remark, a.data_source = b.data_source, a.cx_class1_plan = b.cx_class1_plan, a.cx_class2_plan = b.cx_class2_plan, a.cx_class3_plan = b.cx_class3_plan, a.cx_class4_plan = b.cx_class4_plan, a.cx_class5_plan = b.cx_class5_plan WHEN NOT MATCHED THEN INSERT (a.ID,a.SCHEDULE_DATE,a.CX_BATCH_NO,a.BATCH_NO,a.ORDER_NO,a.BEAD_CODE,a.STEEL_RING_CODE,a.TRIANGLE_GLUE_CODE,a.GLUE_CODE,a.MOUTH_PLATE_CODE,a.SPEC_SIZE,a.MACHINE_ID,a.UNIT_CONSUME,a.STOCK_QTY,a.SUPPLY_TIME,a.MID_PLAN_QTY,a.MID_PRODUCE_ORDER,a.MID_SYS_ANALYSIS,a.MID_HAND_ANALYSIS,a.NIGHT_PLAN_QTY,a.NIGHT_PRODUCE_ORDER,a.NIGHT_SYS_ANALYSIS,a.NIGHT_HAND_ANALYSIS,a.DAY_PLAN_QTY,a.DAY_PRODUCE_ORDER,a.DAY_SYS_ANALYSIS,a.DAY_HAND_ANALYSIS,a.NEXT_MID_PLAN_QTY,a.NEXT_MID_PRODUCE_ORDER,a.NEXT_MID_SYS_ANALYSIS,a.NEXT_MID_HAND_ANALYSIS,a.CX_CLASS1_PLAN,a.CX_CLASS2_PLAN,a.CX_CLASS3_PLAN,a.CX_CLASS4_PLAN,a.CX_CLASS5_PLAN,a.IS_RELEASE,a.MARK_CLOSE_OUT_TIP,a.PRODUCTION_STATUS,a.REMARK,a.DEL_FLAG,a.CREATE_BY,a.CREATE_TIME,a.data_Source) values (SEQ_TQ_SCHEDULE.NEXTVAL,b.SCHEDULE_DATE,b.CX_BATCH_NO,b.BATCH_NO,b.ORDER_NO,b.BEAD_CODE,b.STEEL_RING_CODE,b.TRIANGLE_GLUE_CODE,b.GLUE_CODE,b.MOUTH_PLATE_CODE,b.SPEC_SIZE,b.MACHINE_ID,b.UNIT_CONSUME,b.STOCK_QTY,b.SUPPLY_TIME,b.MID_PLAN_QTY,b.MID_PRODUCE_ORDER,b.MID_SYS_ANALYSIS,b.MID_HAND_ANALYSIS,b.NIGHT_PLAN_QTY,b.NIGHT_PRODUCE_ORDER,b.NIGHT_SYS_ANALYSIS,b.NIGHT_HAND_ANALYSIS,b.DAY_PLAN_QTY,b.DAY_PRODUCE_ORDER,b.DAY_SYS_ANALYSIS,b.DAY_HAND_ANALYSIS,b.NEXT_MID_PLAN_QTY,b.NEXT_MID_PRODUCE_ORDER,b.NEXT_MID_SYS_ANALYSIS,b.NEXT_MID_HAND_ANALYSIS,b.CX_CLASS1_PLAN,b.CX_CLASS2_PLAN,b.CX_CLASS3_PLAN,b.CX_CLASS4_PLAN,b.CX_CLASS5_PLAN,b.IS_RELEASE,b.MARK_CLOSE_OUT_TIP,b.PRODUCTION_STATUS,b.REMARK,b.DEL_FLAG,b.CREATE_BY,b.CREATE_TIME,b.data_Source)
